/// Lines over time with axes and a legend; `live` keeps the newest window in
/// view.
#[derive(Clone, Debug, PartialEq)]
pub struct LineChart {
    /// The rows: an x column and a column a series.
    pub data: Channel,
    /// The x column (time, an index).
    pub x: String,
    /// The lines.
    pub series: Vec<Series>,
    /// In px; 160 when left out.
    pub height: Option<f64>,
    /// Filled under the first line.
    pub area: Option<bool>,
    /// The x window's start, held by the host: a chart that shares its axis
    /// with another view (a timeline's lanes). With `x_max`; the data's own
    /// range when left out.
    pub x_min: Option<f64>,
    /// The x window's end, held by the host.
    pub x_max: Option<f64>,
    /// The y labels' column in px, held: charts stacked under one another, or
    /// under a waterfall with the same `gutter`, share their plot's left edge.
    /// As wide as the widest label when left out.
    pub gutter: Option<f64>,
    /// With it, only the last `window` of x is shown: a live chart. While
    /// samples come in it scrolls smoothly between them, drawn one sample
    /// behind and slid left over the time samples take to come (a keyframe
    /// cycle the core runs, so a frame between samples runs no view); under
    /// reduced motion, and while the plot is out of the viewport, it steps.
    pub window: Option<f64>,
    /// How the x ticks read; the number when left out.
    pub x_format: Option<XFormat>,
    /// After each x tick's number: `min`, `s`.
    pub x_unit: Option<String>,
    /// After each y tick's number: `ms`, `%`.
    pub y_unit: Option<String>,
    /// Under the pointer, a crosshair at the pointer's x, a dot on each series
    /// there and a readout of the x and every series' value in its colour for
    /// the sample under it — a still pointer keeps its crosshair still while
    /// a live window slides samples under it — gone when the pointer leaves;
    /// on when left out. An idle chart pays one hover layer for it.
    pub readout: Option<bool>,
    /// A Tab stop that is a slider over the samples: the arrows move the
    /// readout a sample, Page Up and Down ten, Home and End to the ends, and a
    /// screen reader hears the readout as its value and as a live region. No
    /// key sink: every other key, Tab and the app's chords, goes on as from any
    /// control. Left out, the chart is no Tab stop; the pointer's readout works
    /// either way.
    pub focusable: Option<bool>,
    /// The message `hover` arrives as, with `hover: LineChartHover` in it. The
    /// pointer moved over a row.
    pub on_hover: Option<Value>,
    /// Keys the instance; by default it is keyed by where it is placed.
    pub key: Option<String>,
    /// Asks the extension every frame instead of replaying an unchanged instance.
    pub fresh: bool,
}

impl LineChart {
    /// What it needs; the rest by their setters.
    pub fn new(data: Channel, x: impl Into<String>, series: Vec<Series>) -> Self {
        Self {
            data,
            x: x.into(),
            series,
            height: None,
            area: None,
            x_min: None,
            x_max: None,
            gutter: None,
            window: None,
            x_format: None,
            x_unit: None,
            y_unit: None,
            readout: None,
            focusable: None,
            on_hover: None,
            key: None,
            fresh: false,
        }
    }

    /// In px; 160 when left out.
    pub fn height(mut self, v: f64) -> Self {
        self.height = Some(v);
        self
    }

    /// Filled under the first line.
    pub fn area(mut self, v: bool) -> Self {
        self.area = Some(v);
        self
    }

    /// The x window's start, held by the host: a chart that shares its axis
    /// with another view (a timeline's lanes). With `x_max`; the data's own
    /// range when left out.
    pub fn x_min(mut self, v: f64) -> Self {
        self.x_min = Some(v);
        self
    }

    /// The x window's end, held by the host.
    pub fn x_max(mut self, v: f64) -> Self {
        self.x_max = Some(v);
        self
    }

    /// The y labels' column in px, held: charts stacked under one another, or
    /// under a waterfall with the same `gutter`, share their plot's left edge.
    /// As wide as the widest label when left out.
    pub fn gutter(mut self, v: f64) -> Self {
        self.gutter = Some(v);
        self
    }

    /// With it, only the last `window` of x is shown: a live chart. While
    /// samples come in it scrolls smoothly between them, drawn one sample
    /// behind and slid left over the time samples take to come (a keyframe
    /// cycle the core runs, so a frame between samples runs no view); under
    /// reduced motion, and while the plot is out of the viewport, it steps.
    pub fn window(mut self, v: f64) -> Self {
        self.window = Some(v);
        self
    }

    /// How the x ticks read; the number when left out.
    pub fn x_format(mut self, v: XFormat) -> Self {
        self.x_format = Some(v);
        self
    }

    /// After each x tick's number: `min`, `s`.
    pub fn x_unit(mut self, v: impl Into<String>) -> Self {
        self.x_unit = Some(v.into());
        self
    }

    /// After each y tick's number: `ms`, `%`.
    pub fn y_unit(mut self, v: impl Into<String>) -> Self {
        self.y_unit = Some(v.into());
        self
    }

    /// Under the pointer, a crosshair at the pointer's x, a dot on each series
    /// there and a readout of the x and every series' value in its colour for
    /// the sample under it — a still pointer keeps its crosshair still while
    /// a live window slides samples under it — gone when the pointer leaves;
    /// on when left out. An idle chart pays one hover layer for it.
    pub fn readout(mut self, v: bool) -> Self {
        self.readout = Some(v);
        self
    }

    /// A Tab stop that is a slider over the samples: the arrows move the
    /// readout a sample, Page Up and Down ten, Home and End to the ends, and a
    /// screen reader hears the readout as its value and as a live region. No
    /// key sink: every other key, Tab and the app's chords, goes on as from any
    /// control. Left out, the chart is no Tab stop; the pointer's readout works
    /// either way.
    pub fn focusable(mut self, v: bool) -> Self {
        self.focusable = Some(v);
        self
    }

    /// The message `hover` arrives as. The pointer moved over a row.
    pub fn on_hover(mut self, msg: impl Into<Value>) -> Self {
        self.on_hover = Some(msg.into());
        self
    }

    /// Keys the instance.
    pub fn key(mut self, key: impl Into<String>) -> Self {
        self.key = Some(key.into());
        self
    }

    /// Asks the extension every frame.
    pub fn fresh(mut self) -> Self {
        self.fresh = true;
        self
    }

    /// The props as the extension reads them.
    pub fn props(&self) -> Value {
        let mut m: Vec<(String, Value)> = Vec::new();
        m.push(("data".into(), (&self.data).handle()));
        m.push(("x".into(), Value::str((&self.x).as_str())));
        m.push((
            "series".into(),
            Value::List((&self.series).iter().map(|x| x.to_value()).collect()),
        ));
        if let Some(v) = &self.height {
            m.push(("height".into(), Value::Float(*v)));
        }
        if let Some(v) = &self.area {
            m.push(("area".into(), Value::Bool(*v)));
        }
        if let Some(v) = &self.x_min {
            m.push(("x_min".into(), Value::Float(*v)));
        }
        if let Some(v) = &self.x_max {
            m.push(("x_max".into(), Value::Float(*v)));
        }
        if let Some(v) = &self.gutter {
            m.push(("gutter".into(), Value::Float(*v)));
        }
        if let Some(v) = &self.window {
            m.push(("window".into(), Value::Float(*v)));
        }
        if let Some(v) = &self.x_format {
            m.push(("x_format".into(), v.to_value()));
        }
        if let Some(v) = &self.x_unit {
            m.push(("x_unit".into(), Value::str(v.as_str())));
        }
        if let Some(v) = &self.y_unit {
            m.push(("y_unit".into(), Value::str(v.as_str())));
        }
        if let Some(v) = &self.readout {
            m.push(("readout".into(), Value::Bool(*v)));
        }
        if let Some(v) = &self.focusable {
            m.push(("focusable".into(), Value::Bool(*v)));
        }
        if let Some(v) = &self.on_hover {
            m.push(("on_hover".into(), v.clone()));
        }
        if let Some(k) = &self.key {
            m.push(("key".into(), Value::str(k.as_str())));
        }
        if self.fresh {
            m.push(("fresh".into(), Value::Bool(true)));
        }
        Value::Map(m)
    }

    /// Places it under `kit/line_chart`.
    pub fn place(&self, ui: &mut Ui<'_>) -> Option<FillAnswer> {
        ui.component("kit/line_chart", &self.props())
    }

    /// Places it under `<namespace>/line_chart`.
    pub fn place_in(&self, ui: &mut Ui<'_>, namespace: &str) -> Option<FillAnswer> {
        ui.component(&format!("{namespace}/line_chart"), &self.props())
    }
}

